/**
 * Types of the canonical citation extractor (citations-v2). The pattern table is generated by
 * scripts/citations_v2/build_patterns.py; the Python engine (scripts/citations_v2/engine.py) and the TypeScript engine
 * (engine.ts) produce the same Citation objects for the same text (golden fixtures run by both test suites).
 */

export type PatternRule = {
  id: string;
  kind: string;
  builder: string;
  priority: number;
  pattern: string;
  flags: string;
  anchors: string[];
  family?: string;
  item?: string;
  const?: Record<string, string>;
  key?: string;
  normalized?: string;
  fields?: Record<string, string>;
  pin?: string;
  pin_group?: string;
  required?: string[];
  nonzero?: string;
  state?: string;
  code?: string;
  atomic?: Record<string, string>;
};

export type PatternTable = {
  version: string;
  source: Record<string, string>;
  rules: PatternRule[];
  case: {
    signals: string;
    name_tail: string;
    abbreviations: string[];
    paren: string;
    pin: string;
    join: string;
  };
  pins: Record<string, string>;
  reporters: Record<string, string[]>;
  reporter_names: Record<string, string>;
  states: Record<string, string>;
  state_abbr: Record<string, string>;
  rule_sets: Record<string, string>;
  rule_set_names: Record<string, string>;
  dotted_states: string[];
};

export type CitationKind =
  | "case"
  | "usc"
  | "cfr"
  | "cfr_part"
  | "federal_register"
  | "statutes_at_large"
  | "public_law"
  | "constitution_us"
  | "constitution_state"
  | "federal_rule"
  | "local_rule"
  | "state_statute"
  | "state_regulation"
  | "mdl"
  | "docket"
  /** a short form whose antecedent was not found (its kind is the antecedent's kind once linked) */
  | "short";

export type ShortForm = "id" | "at" | "supra" | "section" | "rule";

export type Antecedent = number | { page: number; index: number };

export type Citation = {
  kind: CitationKind;
  form: "full" | "short";
  short: ShortForm | null;
  /** id of the pattern-table rule that read it */
  rule: string;
  /** code-point offsets of `matched` in the input ([start, end)) */
  start: number;
  end: number;
  matched: string;
  /** the whole match (a statutory list shares one span across its items) */
  span: [number, number];
  /** authority key ("usc:42:1983", "case:550:U.S.:544", "state-stat:CA:busprof:17200"); null for an unlinked short form */
  key: string | null;
  normalized: string;
  pin: string | null;
  fields: Record<string, string>;
  /** parallel citations of one decision share a group number */
  group: number | null;
  name: { text: string; start: number; end: number } | null;
  paren: { court: string; year: string; date: string; start: number; end: number } | null;
  antecedent: Antecedent | null;
  /** short forms only: resolved (antecedent found), ambiguous (more than one possible), none */
  short_status: "resolved" | "ambiguous" | "none" | null;
};
